use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();
    let kata: Vec<String> = it
        .map(|k| {
            let mut cs = k.chars();
            let a = cs.next().unwrap().to_uppercase().collect::<String>();
            a + cs.as_str()
        })
        .collect();
    println!("{}", kata.join(" "));
}

