use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut baris = input.lines();
    let k: u8 = baris.next().unwrap().trim().parse().unwrap();
    let pesan = baris.next().unwrap_or("");
    let hasil: String = pesan
        .chars()
        .map(|c| if c.is_ascii_lowercase() { (b'a' + (c as u8 - b'a' + k) % 26) as char } else { c })
        .collect();
    println!("{}", hasil);
}

